
.section {
  border-bottom: 1px solid var(--c-border);

  &:last-child {
    border-bottom: none;
  }
}

.section-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  cursor: pointer;
  user-select: none;
  transition: background 0.15s;

  &:hover {
    background: var(--c-surface);
  }
}

.section-icon {
  font-size: 13px;
}

.cloth-icon {
  color: var(--c-cloth-accent);
}

.section-label {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--c-text-dim);
}

.section-arrow {
  margin-left: auto;
  font-size: 10px;
  color: var(--c-text-muted);
  transition: transform 0.2s;
}

.section-body {
  padding: 0 16px 12px;
  animation: slideDown 0.25s ease;
}

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}

.cloth-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.cloth-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 10px;
  background: var(--c-surface-alt);
  border-radius: 6px;
  border: 1px solid transparent;
  transition: border-color 0.2s;

  &:hover {
    border-color: var(--c-cloth-accent);
  }
}

.cloth-key {
  font-size: 11px;
  color: var(--c-text-muted);
  min-width: 28px;
  text-align: right;
}

.cloth-val {
  font-size: 13px;
  color: var(--c-text);
  flex: 1;
}
