
.section {
  border-bottom: 1px solid var(--c-border);

  &:last-child {
    border-bottom: none;
  }
}

.section-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  cursor: pointer;
  user-select: none;
  transition: background 0.15s;

  &:hover {
    background: var(--c-surface);
  }
}

.section-icon {
  font-size: 13px;
}

.body-icon {
  color: var(--c-body-accent);
}

.section-label {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--c-text-dim);
}

.section-arrow {
  margin-left: auto;
  font-size: 10px;
  color: var(--c-text-muted);
  transition: transform 0.2s;
}

.section-body {
  padding: 0 16px 12px;
  animation: slideDown 0.25s ease;
}

@keyframes slideDown {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.body-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.body-item {
  background: var(--c-surface-alt);
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 10px;
  transition: border-color 0.2s;

  &:hover {
    border-color: var(--c-body-accent);
  }
}

.body-item-header {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 6px;
}

.body-item-icon {
  font-size: 11px;
  color: var(--c-body-accent);
}

.body-item-label {
  font-size: 11px;
  color: var(--c-text-muted);
}

.body-item-value {
  font-size: 13px;
  color: var(--c-text);
  line-height: 1.5;
  min-height: 18px;
}
