
.section {
  border-bottom: 1px solid var(--c-border);

  &:last-child {
    border-bottom: none;
  }
}

.section-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  cursor: pointer;
  user-select: none;
  transition: background 0.15s;

  &:hover {
    background: var(--c-surface);
  }
}

.section-icon {
  font-size: 13px;
}

.emotion-icon {
  color: var(--c-emotion-accent);
}

.section-label {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--c-text-dim);
}

.section-arrow {
  margin-left: auto;
  font-size: 10px;
  color: var(--c-text-muted);
  transition: transform 0.2s;
}

.section-body {
  padding: 0 16px 12px;
  animation: slideDown 0.25s ease;
}

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}

.emotion-card {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  background: var(--c-surface-alt);
  border: 1px solid var(--c-border);
  border-radius: 10px;
  overflow: hidden;

  .emotion-glow {
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse at 20% 50%, var(--c-emotion-accent) 0%, transparent 70%);
    opacity: 0.08;
    pointer-events: none;
  }
}

.emotion-face {
  font-size: 24px;
  color: var(--c-emotion-accent);
  z-index: 1;
}

.emotion-text {
  font-size: 14px;
  color: var(--c-text);
  line-height: 1.5;
  z-index: 1;
}
